-- 002 - Domain tables (generated by scripts/generate-sql.js - do not edit by hand).
-- One real table per Fieldwise resource, replacing the generic farm_records.data jsonb store.
-- Requires 001_core.sql first. Needs PostgreSQL 15+ (ON DELETE SET NULL (column)), which all
-- current Supabase projects provide.
--
-- Every row carries farm_id; composite foreign keys (farm_id, ref_id) make cross-farm links
-- impossible. Keys the app does not map to a column are kept in the `extra` jsonb column.

create or replace function public.set_updated_at()
returns trigger
language plpgsql
set search_path = public, pg_temp
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

-- Owners, managers and workers may change farm data; viewers are read-only.
create or replace function public.can_write_farm(p_farm_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
    from public.farm_members m
    where m.farm_id = p_farm_id
      and m.user_id = (select auth.uid())
      and m.role in ('owner', 'manager', 'worker')
  );
$$;

revoke all on function public.can_write_farm(uuid) from public, anon;
grant execute on function public.can_write_farm(uuid) to authenticated;

-- crop-fields
create table if not exists public.crop_fields (
  id uuid primary key default gen_random_uuid(),
  farm_id uuid not null references public.farms (id) on delete cascade,
  created_by uuid default auth.uid() references auth.users (id) on delete set null,
  name text not null,
  size numeric not null,
  unit text not null,
  soil_type text not null default '',
  notes text not null default '',
  extra jsonb not null default '{}'::jsonb check (jsonb_typeof(extra) = 'object'),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint crop_fields_farm_id_id_key unique (farm_id, id),
  constraint crop_fields_size_min check (size >= 0)
);
create index if not exists crop_fields_farm_created_idx on public.crop_fields (farm_id, created_at desc);
drop trigger if exists set_updated_at on public.crop_fields;
create trigger set_updated_at before update on public.crop_fields
  for each row execute function public.set_updated_at();
alter table public.crop_fields enable row level security;
revoke all on public.crop_fields from anon, public;
grant select, insert, update, delete on public.crop_fields to authenticated;
drop policy if exists "Farm members can view crop_fields" on public.crop_fields;
create policy "Farm members can view crop_fields"
  on public.crop_fields for select to authenticated
  using (public.is_farm_member(farm_id));
drop policy if exists "Farm editors can insert crop_fields" on public.crop_fields;
create policy "Farm editors can insert crop_fields"
  on public.crop_fields for insert to authenticated
  with check (public.can_write_farm(farm_id));
drop policy if exists "Farm editors can update crop_fields" on public.crop_fields;
create policy "Farm editors can update crop_fields"
  on public.crop_fields for update to authenticated
  using (public.can_write_farm(farm_id))
  with check (public.can_write_farm(farm_id));
drop policy if exists "Farm editors can delete crop_fields" on public.crop_fields;
create policy "Farm editors can delete crop_fields"
  on public.crop_fields for delete to authenticated
  using (public.can_write_farm(farm_id));

